"use client";

import { motion } from "motion/react";
import { type ReactNode, useId, useMemo } from "react";
import { useChartStable } from "./chart-context";
import { firstIndexOnOrAfter, toValidDate } from "./date-ranges";
import { type PatternPresetId, renderPatternPreset } from "./pattern-preset";
import { type CategorySlots, useCategorySlots } from "./use-category-slots";
import { isReferenceAreaVisiblePhase } from "./y-domain-utils";

export type DeadlineFillType = "pattern" | "solid" | "gradient" | "none";

export type DeadlineDate = Date | number | string;

export interface DeadlineProps {
  /** Date of the marker line (left edge of the region). */
  date: DeadlineDate;
  /** Where the region ends. Default: the right edge of the plot. */
  endDate?: DeadlineDate;
  /** Line and fill colour. Default: `var(--chart-negative)` (red) */
  color?: string;
  /** Default: `"pattern"` (diagonal stripes). `"none"` draws only the line. */
  fillType?: DeadlineFillType;
  /** Default: 0.6 for `pattern`, 0.12 for `solid`, 0.25 for `gradient`. */
  fillOpacity?: number;
  /** `gradient` only — opacity at the region's right edge. Default: 0 */
  gradientToOpacity?: number;
  /** Pattern preset when `fillType` is `"pattern"`. Default: `"diagonal"` */
  pattern?: PatternPresetId;
  /** Default: 1.5 */
  patternScale?: number;
  /** Default: 1 */
  patternStrokeWidth?: number;
  /** Fade the region out towards its right edge. Default: true */
  fade?: boolean;
  /** Fraction (0–1) of the region, measured from the right, that fades. Default: 0.5 */
  fadeLength?: number;
  /** Draw the vertical marker line. Default: true */
  showLine?: boolean;
  /** Line colour. Default: `color` */
  stroke?: string;
  /** Default: 1 */
  strokeWidth?: number;
  /** Default: undefined (solid). */
  strokeDasharray?: string;
  /** Default: 1 */
  strokeOpacity?: number;
  /** Text drawn beside the marker line. */
  label?: string;
  /** Default: `"top"` */
  labelPosition?: "top" | "bottom";
  /** Default: `color` */
  labelColor?: string;
  /**
   * Band (bar chart) scales only — data key holding each row's date. Default:
   * first field holding a `Date` or `"YYYY-MM-DD"` string.
   */
  dateKey?: string;
  className?: string;
}

const DEFAULT_COLOR = "var(--chart-negative, var(--color-red-500))";
const ENTER_FADE_MS = 420;
const LABEL_INSET = 6;
const LABEL_FLIP_WIDTH = 96;

function defaultFillOpacity(fillType: DeadlineFillType): number {
  if (fillType === "pattern") {
    return 0.6;
  }
  if (fillType === "gradient") {
    return 0.25;
  }
  return 0.12;
}

interface DeadlineRegion {
  /** Unclipped pixel bounds — fade gradients stay pinned to data while panning. */
  x0: number;
  x1: number;
}

function resolveDeadlineRegion(
  startTime: number | undefined,
  endTime: number | undefined,
  {
    innerWidth,
    slots,
    isBandScale,
    xScale,
  }: {
    innerWidth: number;
    slots: CategorySlots | null;
    isBandScale: boolean;
    xScale: (value: Date) => number;
  }
): DeadlineRegion | null {
  if (startTime == null) {
    return null;
  }
  if (slots) {
    if (slots.axis !== "x") {
      return null;
    }
    const startIndex = firstIndexOnOrAfter(slots.dates, new Date(startTime));
    if (startIndex < 0) {
      return null;
    }
    const endIndex =
      endTime == null
        ? -1
        : firstIndexOnOrAfter(slots.dates, new Date(endTime));
    return {
      x0: slots.slotStart(startIndex),
      x1: endIndex < 0 ? innerWidth : slots.slotStart(endIndex),
    };
  }
  if (isBandScale) {
    return null;
  }
  return {
    x0: xScale(new Date(startTime)),
    x1: endTime == null ? innerWidth : xScale(new Date(endTime)),
  };
}

interface DeadlineRegionFillProps {
  region: DeadlineRegion;
  clipX0: number;
  clipX1: number;
  innerHeight: number;
  uid: string;
  color: string;
  fillType: DeadlineFillType;
  opacity: number;
  gradientToOpacity: number;
  patternNode: ReactNode;
  patternId: string;
  fade: boolean;
  fadeLength: number;
}

function DeadlineRegionFill({
  region,
  clipX0,
  clipX1,
  innerHeight,
  uid,
  color,
  fillType,
  opacity,
  gradientToOpacity,
  patternNode,
  patternId,
  fade,
  fadeLength,
}: DeadlineRegionFillProps) {
  const fadeMaskId = `chart-deadline-fade-${uid}`;
  const fillGradientId = `chart-deadline-fill-${uid}`;
  const fadeStart = 1 - Math.min(1, Math.max(0, fadeLength));
  const useFade = fade && fadeLength > 0;
  let regionFill = color;
  if (fillType === "gradient") {
    regionFill = `url(#${fillGradientId})`;
  } else if (patternNode) {
    regionFill = `url(#${patternId})`;
  }
  const gradientAttrs = {
    gradientUnits: "userSpaceOnUse" as const,
    x1: region.x0,
    x2: region.x1,
    y1: 0,
    y2: 0,
  };

  return (
    <>
      <defs>
        {useFade ? (
          <>
            <linearGradient id={`${fadeMaskId}-gradient`} {...gradientAttrs}>
              <stop offset={0} stopColor="white" stopOpacity={1} />
              <stop offset={fadeStart} stopColor="white" stopOpacity={1} />
              <stop offset={1} stopColor="white" stopOpacity={0} />
            </linearGradient>
            <mask id={fadeMaskId}>
              <rect
                fill={`url(#${fadeMaskId}-gradient)`}
                height={innerHeight}
                width={clipX1 - clipX0}
                x={clipX0}
                y={0}
              />
            </mask>
          </>
        ) : null}
        {fillType === "gradient" ? (
          <linearGradient id={fillGradientId} {...gradientAttrs}>
            <stop offset={0} stopColor={color} stopOpacity={1} />
            <stop
              offset={1}
              stopColor={color}
              stopOpacity={opacity > 0 ? gradientToOpacity / opacity : 0}
            />
          </linearGradient>
        ) : null}
      </defs>
      {patternNode}
      <rect
        fill={regionFill}
        height={innerHeight}
        mask={useFade ? `url(#${fadeMaskId})` : undefined}
        opacity={opacity}
        width={clipX1 - clipX0}
        x={clipX0}
        y={0}
      />
    </>
  );
}

function DeadlineMarkerLine({
  x,
  innerHeight,
  color,
  stroke,
  strokeWidth,
  strokeDasharray,
  strokeOpacity,
  label,
  labelColor,
  labelPosition,
  labelFlipped,
}: {
  x: number;
  innerHeight: number;
  color: string;
  stroke?: string;
  strokeWidth: number;
  strokeDasharray?: string;
  strokeOpacity: number;
  label?: string;
  labelColor?: string;
  labelPosition: "top" | "bottom";
  labelFlipped: boolean;
}) {
  const bottom = labelPosition === "bottom";
  return (
    <>
      <line
        stroke={stroke ?? color}
        strokeDasharray={strokeDasharray}
        strokeOpacity={strokeOpacity}
        strokeWidth={strokeWidth}
        x1={x}
        x2={x}
        y1={0}
        y2={innerHeight}
      />
      {label ? (
        <text
          dominantBaseline={bottom ? "auto" : "hanging"}
          fill={labelColor ?? color}
          fontSize={11}
          fontWeight={500}
          textAnchor={labelFlipped ? "end" : "start"}
          x={labelFlipped ? x - LABEL_INSET : x + LABEL_INSET}
          y={bottom ? innerHeight - LABEL_INSET : LABEL_INSET}
        >
          {label}
        </text>
      ) : null}
    </>
  );
}

/**
 * Due-date / point-of-no-return marker: a vertical line at `date` with a
 * region extending right (to `endDate` or the plot edge) that fades out.
 * Works on time scales (line / area / composed) and vertical bar charts.
 */
export function Deadline({
  date,
  endDate,
  color = DEFAULT_COLOR,
  fillType = "pattern",
  fillOpacity,
  gradientToOpacity = 0,
  pattern = "diagonal",
  patternScale = 1.5,
  patternStrokeWidth = 1,
  fade = true,
  fadeLength = 0.5,
  showLine = true,
  stroke,
  strokeWidth = 1,
  strokeDasharray,
  strokeOpacity = 1,
  label,
  labelPosition = "top",
  labelColor,
  dateKey,
  className,
}: DeadlineProps) {
  const {
    innerWidth,
    innerHeight,
    xScale,
    barScale,
    chartPhase,
    enterTransition,
  } = useChartStable();
  const slots = useCategorySlots(dateKey);
  const uid = useId().replace(/:/g, "");
  const patternId = `chart-deadline-pattern-${uid}`;

  const startTime = toValidDate(date)?.getTime();
  const endTime = endDate == null ? undefined : toValidDate(endDate)?.getTime();
  const isBandScale = barScale != null;

  const region = useMemo(
    () =>
      innerWidth > 0 && innerHeight > 0
        ? resolveDeadlineRegion(startTime, endTime, {
            innerWidth,
            slots,
            isBandScale,
            xScale,
          })
        : null,
    [startTime, endTime, innerWidth, innerHeight, slots, isBandScale, xScale]
  );

  const usesPattern = fillType === "pattern" && pattern !== "none";
  const patternNode = useMemo(
    () =>
      usesPattern
        ? renderPatternPreset(pattern, patternId, {
            color,
            scale: patternScale,
            strokeWidth: patternStrokeWidth,
          })
        : null,
    [usesPattern, pattern, patternId, color, patternScale, patternStrokeWidth]
  );

  if (!region || region.x1 <= region.x0) {
    return null;
  }

  const { x0 } = region;
  const clipX0 = Math.max(0, x0);
  const clipX1 = Math.min(innerWidth, region.x1);
  const lineVisible = showLine && x0 >= 0 && x0 <= innerWidth;
  const hasFill = fillType !== "none" && clipX1 > clipX0;
  if (!(lineVisible || hasFill)) {
    return null;
  }

  const visible = isReferenceAreaVisiblePhase(chartPhase);
  const fadeTransition =
    enterTransition && typeof enterTransition === "object"
      ? enterTransition
      : { duration: ENTER_FADE_MS / 1000, ease: "easeOut" as const };

  return (
    <motion.g
      animate={{ opacity: visible ? 1 : 0 }}
      aria-hidden="true"
      className={className ?? "chart-deadline"}
      initial={{ opacity: 0 }}
      transition={fadeTransition}
    >
      {hasFill ? (
        <DeadlineRegionFill
          clipX0={clipX0}
          clipX1={clipX1}
          color={color}
          fade={fade}
          fadeLength={fadeLength}
          fillType={fillType}
          gradientToOpacity={gradientToOpacity}
          innerHeight={innerHeight}
          opacity={fillOpacity ?? defaultFillOpacity(fillType)}
          patternId={patternId}
          patternNode={patternNode}
          region={region}
          uid={uid}
        />
      ) : null}
      {lineVisible ? (
        <DeadlineMarkerLine
          color={color}
          innerHeight={innerHeight}
          label={label}
          labelColor={labelColor}
          labelFlipped={x0 > innerWidth - LABEL_FLIP_WIDTH}
          labelPosition={labelPosition}
          stroke={stroke}
          strokeDasharray={strokeDasharray}
          strokeOpacity={strokeOpacity}
          strokeWidth={strokeWidth}
          x={x0}
        />
      ) : null}
    </motion.g>
  );
}

Deadline.displayName = "Deadline";

export default Deadline;

/** Day-of-week numbers as returned by `Date#getDay()` (0 = Sunday … 6 = Saturday). */
export type WeekdayIndex = 0 | 1 | 2 | 3 | 4 | 5 | 6;

/** Saturday + Sunday. */
export const DEFAULT_WEEKEND_DAYS: readonly WeekdayIndex[] = [6, 0];

/**
 * How a highlighted day maps onto the x axis.
 * - `"calendar"` — midnight to midnight (points at 00:00 sit on the band's left edge)
 * - `"centered"` — shifted half a day earlier so each day's point / column sits in the middle
 */
export type DateRangeAlign = "calendar" | "centered";

export interface DateRange {
  start: Date;
  end: Date;
}

export interface ComputeWeekendRangesOptions {
  weekendDays?: readonly number[];
  /** Use UTC day boundaries instead of local time. Default: false */
  utc?: boolean;
  align?: DateRangeAlign;
  /** Bail out (return `[]`) when the domain spans more days than this. Default: 20_000 */
  maxDays?: number;
}

const HALF_DAY_MS = 12 * 60 * 60 * 1000;
const DAY_MS = 24 * 60 * 60 * 1000;

function startOfDay(date: Date, utc: boolean): Date {
  return utc
    ? new Date(
        Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate())
      )
    : new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

/** Next midnight — calendar arithmetic so DST days stay aligned. */
function addDays(date: Date, days: number, utc: boolean): Date {
  return utc
    ? new Date(
        Date.UTC(
          date.getUTCFullYear(),
          date.getUTCMonth(),
          date.getUTCDate() + days
        )
      )
    : new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

export function isWeekendDate(
  date: Date,
  weekendDays: readonly number[] = DEFAULT_WEEKEND_DAYS,
  utc = false
): boolean {
  const day = utc ? date.getUTCDay() : date.getDay();
  return weekendDays.includes(day);
}

/**
 * Contiguous weekend spans that intersect `[domainStart, domainEnd]`, clipped
 * to the domain. Consecutive weekend days merge into one range (Sat + Sun →
 * one span; Fri + Sat locales work the same way).
 */
export function computeWeekendRanges(
  domainStart: Date,
  domainEnd: Date,
  options: ComputeWeekendRangesOptions = {}
): DateRange[] {
  const {
    weekendDays = DEFAULT_WEEKEND_DAYS,
    utc = false,
    align = "calendar",
    maxDays = 20_000,
  } = options;

  let lo = domainStart.getTime();
  let hi = domainEnd.getTime();
  if (!(Number.isFinite(lo) && Number.isFinite(hi))) {
    return [];
  }
  if (lo > hi) {
    [lo, hi] = [hi, lo];
  }
  if (weekendDays.length === 0 || (hi - lo) / DAY_MS > maxDays) {
    return [];
  }

  const shift = align === "centered" ? HALF_DAY_MS : 0;
  const ranges: DateRange[] = [];
  let runStart: number | null = null;

  // Start one day early so a centered span (or a span already in progress at
  // the domain start) is still picked up.
  let day = addDays(startOfDay(new Date(lo + shift), utc), -1, utc);
  while (day.getTime() - shift <= hi) {
    const next = addDays(day, 1, utc);
    if (isWeekendDate(day, weekendDays, utc)) {
      if (runStart === null) {
        runStart = day.getTime() - shift;
      }
    } else if (runStart !== null) {
      pushClipped(ranges, runStart, day.getTime() - shift, lo, hi);
      runStart = null;
    }
    day = next;
  }
  if (runStart !== null) {
    pushClipped(ranges, runStart, day.getTime() - shift, lo, hi);
  }
  return ranges;
}

function pushClipped(
  ranges: DateRange[],
  start: number,
  end: number,
  lo: number,
  hi: number
) {
  const s = Math.max(start, lo);
  const e = Math.min(end, hi);
  if (e > s) {
    ranges.push({ start: new Date(s), end: new Date(e) });
  }
}

/**
 * Inclusive `[first, last]` index runs of consecutive weekend rows — for band
 * (category) scales where each row is one column. Rows with no date break a run.
 */
export function computeWeekendIndexRuns(
  dates: ReadonlyArray<Date | null | undefined>,
  options: Pick<ComputeWeekendRangesOptions, "weekendDays" | "utc"> = {}
): [number, number][] {
  const { weekendDays = DEFAULT_WEEKEND_DAYS, utc = false } = options;
  const runs: [number, number][] = [];
  let runStart = -1;
  dates.forEach((date, index) => {
    const weekend =
      date != null &&
      !Number.isNaN(date.getTime()) &&
      isWeekendDate(date, weekendDays, utc);
    if (weekend) {
      if (runStart < 0) {
        runStart = index;
      }
    } else if (runStart >= 0) {
      runs.push([runStart, index - 1]);
      runStart = -1;
    }
  });
  if (runStart >= 0) {
    runs.push([runStart, dates.length - 1]);
  }
  return runs;
}

const ISO_DATE_ONLY = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * Coerce a user date-ish value to a valid `Date` (or `null`). Date-only ISO
 * strings (`"2024-01-06"`) parse as local midnight, not UTC, so the weekday
 * matches the calendar date.
 */
export function toValidDate(value: unknown): Date | null {
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value;
  }
  if (typeof value === "string") {
    const match = ISO_DATE_ONLY.exec(value.trim());
    if (match) {
      return new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
    }
  }
  if (typeof value === "number" || typeof value === "string") {
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? null : date;
  }
  return null;
}

/**
 * Key of the first field in `row` holding a `Date` (or a date-only ISO string).
 * Used to find dates on band-scale (bar) charts whose context only exposes
 * category labels.
 */
export function detectDateKey(
  row: Record<string, unknown> | undefined
): string | null {
  if (!row) {
    return null;
  }
  for (const [key, value] of Object.entries(row)) {
    if (value instanceof Date) {
      return key;
    }
    if (typeof value === "string" && ISO_DATE_ONLY.test(value.trim())) {
      return key;
    }
  }
  return null;
}

/** Index of the first row whose date is on or after `target`; `-1` when none. */
export function firstIndexOnOrAfter(
  dates: ReadonlyArray<Date | null | undefined>,
  target: Date
): number {
  const t = target.getTime();
  return dates.findIndex((date) => date != null && date.getTime() >= t);
}

"use client";

import { useMemo } from "react";
import { useChartStable } from "./chart-context";
import { detectDateKey, toValidDate } from "./date-ranges";

export interface CategorySlots {
  /** Per-row date (null when the row has no parseable date). */
  dates: (Date | null)[];
  /** Leading pixel edge of each row's slot, including half the inner padding. */
  slotStart: (index: number) => number;
  /** Full slot size (`bandwidth + inner padding`). */
  step: number;
  /** `"x"` for vertical bars (columns), `"y"` for horizontal bars. */
  axis: "x" | "y";
}

/**
 * Date lookup for band (category) scales — bar charts expose only category
 * labels in context, so read dates from `dateKey` (auto-detected when omitted).
 * Returns `null` on time / linear scales.
 */
export function useCategorySlots(dateKey?: string): CategorySlots | null {
  const { barScale, barXAccessor, data, orientation } = useChartStable();

  return useMemo(() => {
    if (!(barScale && barXAccessor)) {
      return null;
    }
    const key = dateKey ?? detectDateKey(data[0]);
    const dates = data.map((row) => (key ? toValidDate(row[key]) : null));
    const step = barScale.step();
    const gap = step - barScale.bandwidth();
    return {
      dates,
      step,
      axis: orientation === "horizontal" ? "y" : "x",
      slotStart: (index: number) => {
        const row = data[index];
        const start = row ? barScale(barXAccessor(row)) : undefined;
        return (start ?? 0) - gap / 2;
      },
    };
  }, [barScale, barXAccessor, data, orientation, dateKey]);
}
